/// Lazily built for O(1) membership tests.
///
/// Top-level finals initialize on first use, so the roster costs nothing
/// until something actually renders a badge.
final Set<String> _ogBetaTesterIndex = ogBetaTesterPubkeys.toSet();

/// Whether [pubkey] belongs to a Divine beta tester.
///
/// Accepts any casing and tolerates surrounding whitespace. Returns false
/// for a blank [pubkey].
bool isOgBetaTesterPubkey(String pubkey) {
  final normalized = pubkey.trim().toLowerCase();
  if (normalized.isEmpty) return false;
  return _ogBetaTesterIndex.contains(normalized);
}
